//! Checks PSI-MS / UO (accession, name) pairs against the PSI-MS ontology:
//! the generated `openmassspec_core::cv` terms, every pair the writer emits
//! into a document that exercises each writer path, and every accession
//! literal in this crate's Rust sources.
//!
//! The ontology is not vendored whole (about 2 MB). Instead
//! `tests/data/psi-ms-subset.tsv` holds the OBO entries for every accession
//! that appears in `src/`, `examples/`, and `tests/`, generated by
//! `scripts/extract-cv-subset.sh` (its header records the OBO
//! data-version). Adding a new accession without regenerating the subset
//! fails this test.
//!
//! In code, every accession literal must appear in one of these shapes, so
//! the paired name can be found:
//!
//! - `accession="ACC" name="NAME"` and `unitAccession="ACC" unitName="NAME"`
//!   inside XML strings,
//! - `("ACC", "NAME")` tuples and `CvTerm::new("ACC", "NAME")`,
//! - `accession: "ACC", name: "NAME"...` struct literals (the shape of the
//!   generated `src/cv/terms.rs`).
//!
//! In non-test code an accession literal in any other shape fails the
//! test, so a new emission path cannot slip past it. Test code may also use
//! bare accessions (for example as `contains` needles); those are only
//! checked for existence. Accessions in comments are only checked for
//! existence (and non-obsolescence) in the ontology.

use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};

use openmassspec_core::{
    cv, write_indexed_mzml, write_mzml_with_options, Activation, Analyzer, ChromatogramIter,
    ChromatogramRecord, Compression, CvTerm, MobilityArrayKind, Polarity, PrecursorInfo,
    RunMetadata, ScanMode, SpectrumIter, SpectrumRecord, SpectrumSource, WriteOptions,
};

struct Term {
    name: String,
    obsolete: bool,
}

fn load_subset() -> BTreeMap<String, Term> {
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data/psi-ms-subset.tsv");
    let text = fs::read_to_string(&path).unwrap();
    text.lines()
        .filter(|l| !l.starts_with('#') && !l.is_empty())
        .map(|l| {
            let mut cols = l.split('\t');
            let acc = cols.next().unwrap().to_string();
            let name = cols.next().unwrap().to_string();
            let obsolete = cols.next().unwrap() == "true";
            (acc, Term { name, obsolete })
        })
        .collect()
}

fn rust_files() -> Vec<PathBuf> {
    let root = Path::new(env!("CARGO_MANIFEST_DIR"));
    let mut files = Vec::new();
    for dir in ["src", "examples", "tests"] {
        let mut stack = vec![root.join(dir)];
        while let Some(d) = stack.pop() {
            for entry in fs::read_dir(&d).unwrap() {
                let p = entry.unwrap().path();
                if p.is_dir() {
                    stack.push(p);
                } else if p.extension().is_some_and(|e| e == "rs") {
                    files.push(p);
                }
            }
        }
    }
    files.sort();
    files
}

/// Byte offsets of every `MS:NNNNNNN` / `UO:NNNNNNN` in `s`.
fn accession_positions(s: &str) -> Vec<usize> {
    let b = s.as_bytes();
    let mut out = Vec::new();
    for i in 0..b.len().saturating_sub(9) {
        let prefix = &b[i..i + 3];
        if (prefix == b"MS:" || prefix == b"UO:")
            && b[i + 3..i + 10].iter().all(u8::is_ascii_digit)
            && b.get(i + 10).is_none_or(|c| !c.is_ascii_digit())
            && (i == 0 || !b[i - 1].is_ascii_alphanumeric())
        {
            out.push(i);
        }
    }
    out
}

/// Reads a `"..."` string literal starting at `s[0] == '"'`.
fn string_literal(s: &str) -> Option<&str> {
    let rest = s.strip_prefix('"')?;
    rest.find('"').map(|end| &rest[..end])
}

/// The name paired with the accession at `code[at..at + 10]`, if the
/// literal is in one of the recognised shapes.
fn paired_name(code: &str, at: usize) -> Option<String> {
    let before = &code[..at];
    let after = &code[at + 10..];

    // accession="ACC" name="NAME" / unitAccession="ACC" unitName="NAME"
    for (open, next) in [
        ("unitAccession=\"", "\" unitName=\""),
        ("accession=\"", "\" name=\""),
    ] {
        if before.ends_with(open) {
            let rest = after.strip_prefix(next)?;
            return rest.find('"').map(|end| rest[..end].to_string());
        }
    }

    // JSON: "accession":"ACC","name":"NAME"
    if before.ends_with("\"accession\":\"") {
        let rest = after.strip_prefix("\",\"name\":\"")?;
        return rest.find('"').map(|end| rest[..end].to_string());
    }

    if !before.ends_with('"') || !after.starts_with('"') {
        return None;
    }
    let after = &after[1..];

    // accession: "ACC", ... name: "NAME"
    if before
        .trim_end_matches('"')
        .trim_end()
        .ends_with("accession:")
    {
        let rest = after.trim_start().strip_prefix(',')?.trim_start();
        let rest = rest.strip_prefix("name:")?.trim_start();
        return string_literal(rest).map(str::to_string);
    }

    // ("ACC", "NAME") and CvTerm::new("ACC", "NAME"). A following literal
    // that is itself an accession means a list of accessions, not a pair.
    let rest = after.trim_start().strip_prefix(',')?.trim_start();
    string_literal(rest)
        .filter(|name| accession_positions(name) != [0])
        .map(str::to_string)
}

/// Replaces `//` comment text with spaces (keeping byte offsets), and
/// returns the comment-only text separately. Good enough for this crate's
/// sources: no string literal in them contains `//` followed by an
/// accession.
fn split_comments(src: &str) -> (String, String) {
    let mut code = String::with_capacity(src.len());
    let mut comments = String::new();
    for line in src.split_inclusive('\n') {
        match line.find("//") {
            Some(i) if !line[..i].contains('"') || line.trim_start().starts_with("//") => {
                let body = line[i..].trim_end_matches('\n');
                code.push_str(&line[..i]);
                code.extend(std::iter::repeat_n(' ', body.len()));
                code.push_str(&line[i + body.len()..]);
                comments.push_str(&line[i..]);
            }
            _ => code.push_str(line),
        }
    }
    (code, comments)
}

#[test]
fn every_cv_term_matches_the_psi_ms_ontology() {
    let cv = load_subset();
    let mut problems = Vec::new();
    let mut pairs_checked = 0;

    for file in rust_files() {
        let src = fs::read_to_string(&file).unwrap();
        let rel = file
            .strip_prefix(env!("CARGO_MANIFEST_DIR"))
            .unwrap()
            .display()
            .to_string();
        let (code, comments) = split_comments(&src);
        // Test code (everything in tests/, and from the first `#[cfg(test)]`
        // in other files) may use bare accessions as search needles.
        let test_start = if rel.starts_with("tests") {
            0
        } else {
            code.find("#[cfg(test)]").unwrap_or(code.len())
        };

        for at in accession_positions(&code) {
            let acc = &code[at..at + 10];
            let line = code[..at].matches('\n').count() + 1;
            let Some(term) = cv.get(acc) else {
                problems.push(format!(
                    "{rel}:{line}: {acc} not in tests/data/psi-ms-subset.tsv \
                     (unknown accession, or rerun scripts/extract-cv-subset.sh)"
                ));
                continue;
            };
            if term.obsolete {
                problems.push(format!("{rel}:{line}: {acc} is obsolete"));
            }
            match paired_name(&code, at) {
                Some(name) if name == term.name => pairs_checked += 1,
                Some(name) => problems.push(format!(
                    "{rel}:{line}: {acc} is named {:?} in the CV, source says {name:?}",
                    term.name
                )),
                None if at >= test_start => {}
                None => problems.push(format!(
                    "{rel}:{line}: {acc} is not in a recognised (accession, name) shape; \
                     extend tests/cv_terms.rs"
                )),
            }
        }

        for at in accession_positions(&comments) {
            let acc = &comments[at..at + 10];
            match cv.get(acc) {
                None => problems.push(format!("{rel}: comment cites unknown {acc}")),
                Some(t) if t.obsolete => {
                    problems.push(format!("{rel}: comment cites obsolete {acc}"))
                }
                Some(_) => {}
            }
        }
    }

    assert!(problems.is_empty(), "\n{}", problems.join("\n"));
    // Guard against the scanner silently matching nothing.
    assert!(pairs_checked > 100, "only {pairs_checked} pairs checked");
}

#[test]
fn generated_cv_module_matches_the_psi_ms_ontology() {
    let subset = load_subset();
    let header = fs::read_to_string(
        Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data/psi-ms-subset.tsv"),
    )
    .unwrap();
    assert!(
        header.contains(&format!("data-version {} ", cv::PSI_MS_VERSION)),
        "src/cv/terms.rs and tests/data/psi-ms-subset.tsv come from different OBO releases"
    );
    for term in cv::ALL {
        let Some(t) = subset.get(term.accession()) else {
            panic!("{} missing from the subset", term.accession());
        };
        assert_eq!(t.name, term.name(), "{}", term.accession());
        assert!(!t.obsolete, "{} is obsolete", term.accession());
    }
}

/// A source whose spectra and chromatograms reach every writer branch that
/// emits a cvParam.
struct EveryPath {
    kind: MobilityArrayKind,
}

impl SpectrumSource for EveryPath {
    fn run_metadata(&self) -> RunMetadata {
        RunMetadata::new(
            "every-path.raw",
            CvTerm::new("MS:1000563", "Thermo RAW format"),
            CvTerm::new("MS:1000768", "Thermo nativeID format"),
            CvTerm::new("MS:1001911", "Q Exactive"),
            "cv-test",
            "0",
        )
        .with_instrument_serial_number("SN1".to_string())
        .with_acquisition_software_name("acq".to_string())
        .with_mobility_array_kind(self.kind)
        .with_analyzers(vec![
            Analyzer::ITMS,
            Analyzer::TQMS,
            Analyzer::SQMS,
            Analyzer::TOFMS,
            Analyzer::FTMS,
            Analyzer::Sector,
        ])
    }

    fn iter_spectra<'a>(&'a mut self) -> SpectrumIter<'a> {
        let activations = [
            Activation::HCD,
            Activation::MPID,
            Activation::ETD,
            Activation::CID,
            Activation::ECD,
            Activation::IRMPD,
            Activation::PD,
            Activation::PQD,
            Activation::UVPD,
            Activation::SID,
            Activation::EThcD,
        ];
        let first = SpectrumRecord::new(0, 1, "scan=1")
            .with_polarity(Polarity::Negative)
            .with_scan_mode(ScanMode::Profile)
            .with_filter("f".to_string())
            .with_ion_injection_time_ms(1.0)
            .with_faims_cv(-40.0)
            .with_scan_window(50.0, 1500.0)
            .with_peaks(vec![1.0], vec![1.0])
            .with_inv_mobility_per_peak(vec![0.9]);
        // The writer has no scan-level drift-time term and rejects the
        // combination, so only the 1/K0 run sets the scalar.
        let first = if self.kind == MobilityArrayKind::InverseReducedVsPerCm2 {
            first.with_inv_mobility(0.9)
        } else {
            first
        };
        let mut out = vec![first];
        for (i, act) in activations.into_iter().enumerate() {
            for (j, analyzer) in [Analyzer::FTMS, Analyzer::ITMS].into_iter().enumerate() {
                let n = 1 + 2 * i + j;
                out.push(
                    SpectrumRecord::new(n, n as u32 + 1, format!("scan={}", n + 1))
                        .with_ms_level(2)
                        .with_polarity(Polarity::Positive)
                        .with_scan_mode(ScanMode::Centroid)
                        .with_analyzer(analyzer)
                        .with_precursor(
                            PrecursorInfo::default()
                                .with_target_mz(500.0)
                                .with_isolation_width(1.0)
                                .with_selected_mz(500.0)
                                .with_charge(2)
                                .with_intensity(10.0)
                                .with_ccs(300.0)
                                .with_collision_energy(
                                    30.0,
                                    if j == 0 {
                                        openmassspec_core::CollisionEnergyUnit::Nce
                                    } else {
                                        openmassspec_core::CollisionEnergyUnit::Ev
                                    },
                                )
                                .with_activation(act)
                                .with_analyzer(analyzer),
                        )
                        .with_peaks(vec![1.0], vec![1.0]),
                );
            }
        }
        Box::new(out.into_iter().map(Ok))
    }

    fn iter_chromatograms<'a>(&'a mut self) -> ChromatogramIter<'a> {
        let untyped = ChromatogramRecord::new(0, "untyped", vec![0.0], vec![1.0])
            .with_precursor_mz(500.0)
            .with_product_mz(200.0);
        Box::new(std::iter::once(Ok(untyped)))
    }

    fn additional_processing_steps(&self) -> Vec<CvTerm> {
        vec![cv::PEAK_PICKING.into()]
    }
}

/// `(accession, name)` for every `accession=`/`unitAccession=` attribute
/// pair in `xml`.
fn emitted_pairs(xml: &str) -> Vec<(String, String)> {
    let mut out = Vec::new();
    for (acc_attr, name_attr) in [
        (" accession=\"", "\" name=\""),
        (" unitAccession=\"", "\" unitName=\""),
    ] {
        let mut rest = xml;
        while let Some(at) = rest.find(acc_attr) {
            let tail = &rest[at + acc_attr.len()..];
            let (acc, _) = tail.split_once('"').unwrap();
            let name_tail = tail[acc.len()..]
                .strip_prefix(name_attr)
                .unwrap_or_else(|| panic!("{acc} not followed by its name"));
            let (name, _) = name_tail.split_once('"').unwrap();
            out.push((acc.to_string(), name.to_string()));
            rest = &tail[acc.len()..];
        }
    }
    out
}

#[test]
fn every_emitted_term_matches_the_psi_ms_ontology() {
    let subset = load_subset();
    let mut seen = std::collections::BTreeSet::new();
    for kind in [
        MobilityArrayKind::InverseReducedVsPerCm2,
        MobilityArrayKind::DriftTimeMilliseconds,
    ] {
        for indexed in [false, true] {
            let mut src = EveryPath { kind };
            let mut buf = Vec::new();
            if indexed {
                write_indexed_mzml(&mut src, &mut buf).unwrap();
            } else {
                let opts = WriteOptions::new().with_compression(Compression::NoCompression);
                write_mzml_with_options(&mut src, &mut buf, &opts).unwrap();
            }
            let xml = String::from_utf8(buf).unwrap();
            for (acc, name) in emitted_pairs(&xml) {
                let term = subset
                    .get(&acc)
                    .unwrap_or_else(|| panic!("emitted {acc} is not in the subset"));
                assert_eq!(term.name, name, "emitted {acc}");
                assert!(!term.obsolete, "emitted obsolete {acc}");
                seen.insert(acc);
            }
        }
    }
    // Every generated term is reachable from some writer path.
    for term in cv::ALL {
        assert!(
            seen.contains(term.accession()),
            "{} ({}) is generated but never emitted",
            term.accession(),
            term.name()
        );
    }
}
